css:
.pl2131-container {
    padding: 24px;
    background-color: #f3f5ef;
    color: #1f2a22;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    font-size: 15px;
    line-height: 1.5;
}
.pl2131-container * { box-sizing: border-box; }
.pl2131-header { background-color: #2b4a3a; color: #eef4e8; padding: 22px 26px 20px; border-bottom: 4px solid #4f7a2f; border-radius: 22px 22px 0 0; margin-bottom: 18px; }
.pl2131-header-eyebrow { font-size: 0.72rem; letter-spacing: 0.14em; text-transform: uppercase; color: #c3d6c2; background-color: #2b4a3a; margin-bottom: 6px; }
.pl2131-header h1 { margin: 0; font-size: 1.7rem; font-weight: 700; color: #eef4e8; background-color: #2b4a3a; }
.pl2131-header-sub { margin: 8px 0 0; color: #dbe6d6; background-color: #2b4a3a; max-width: 70ch; }
.pl2131-topbar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; }
.pl2131-period { font-size: 0.9rem; color: #1f2a22; background-color: #ffffff; border: 1px solid #cdd8c8; border-radius: 999px; padding: 6px 14px; }
.pl2131-period-sep { color: #5b6b60; background-color: #ffffff; padding: 0 4px; }
.pl2131-period #roundName { font-weight: 600; }
.pl2131-kpis { display: grid; grid-template-columns: repeat(5, 1fr); gap: 10px; margin-bottom: 18px; }
.pl2131-kpi { background-color: #ffffff; border: 1px solid #cdd8c8; border-radius: 16px; padding: 12px 14px; }
.pl2131-kpi-label { font-size: 0.72rem; letter-spacing: 0.08em; text-transform: uppercase; color: #5b6b60; background-color: #ffffff; min-height: 2.2em; }
.pl2131-kpi-value { font-size: 1.7rem; font-weight: 700; color: #2b4a3a; background-color: #ffffff; line-height: 1.1; margin-top: 4px; font-variant-numeric: tabular-nums; transition: color 0.2s ease; }
.pl2131-kpi-text { font-size: 1.1rem; }
.pl2131-kpi-score { color: #4f7a2f; }
.pl2131-kpi-unit { font-size: 0.75rem; color: #5b6b60; background-color: #ffffff; margin-top: 2px; }
.pl2131-briefing { background-color: #ffffff; border: 1px solid #cdd8c8; border-left: 5px solid #4f7a2f; border-radius: 0 16px 16px 0; padding: 14px 18px; margin-bottom: 16px; }
.pl2131-briefing-label, .pl2131-feedback-label, .pl2131-cash-label, .pl2131-letter-label { font-size: 0.72rem; letter-spacing: 0.12em; text-transform: uppercase; color: #4f7a2f; font-weight: 700; margin-bottom: 6px; }
.pl2131-briefing-text { color: #1f2a22; background-color: #ffffff; max-width: 80ch; }
.pl2131-panel { background-color: #ffffff; border: 1px solid #cdd8c8; border-radius: 16px; padding: 18px 20px; margin-bottom: 16px; }
.pl2131-panel h2 { margin: 0 0 6px; font-size: 1.15rem; font-weight: 700; color: #2b4a3a; background-color: #ffffff; }
.pl2131-panel-intro { margin: 0 0 14px; color: #3f4f45; background-color: #ffffff; max-width: 80ch; }
.pl2131-portfolio { display: grid; grid-template-columns: 1fr; gap: 6px; margin-bottom: 16px; }
.pl2131-prog { display: grid; grid-template-columns: 2.2fr 0.6fr 0.7fr 1.1fr 3fr; gap: 10px; padding: 8px 10px; background-color: #f3f5ef; border: 1px solid #cdd8c8; border-radius: 10px; font-size: 0.82rem; color: #3f4f45; align-items: center; }
.pl2131-prog strong { color: #1f2a22; background-color: #f3f5ef; display: block; }
.pl2131-prog em { color: #5b6b60; background-color: #f3f5ef; font-style: normal; font-size: 0.76rem; }
.pl2131-prog-head { background-color: #ffffff; border-color: #ffffff; color: #5b6b60; font-size: 0.7rem; letter-spacing: 0.08em; text-transform: uppercase; font-weight: 600; }
.pl2131-ev-bad { color: #9a3b2e; background-color: #f3f5ef; }
.pl2131-ev-weak { color: #7a5312; background-color: #f3f5ef; }
.pl2131-ev-ok { color: #3f4f45; background-color: #f3f5ef; }
.pl2131-ev-good { color: #2b4a3a; background-color: #f3f5ef; font-weight: 600; }
.pl2131-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px 18px; }
.pl2131-grid-3 { grid-template-columns: repeat(3, 1fr); }
.pl2131-grid-5 { grid-template-columns: repeat(5, 1fr); }
.pl2131-field label { display: block; font-size: 0.85rem; font-weight: 600; color: #1f2a22; background-color: #ffffff; margin-bottom: 4px; }
.pl2131-field select { width: 100%; padding: 8px 10px; border: 1px solid #93a394; border-radius: 10px; background-color: #ffffff; color: #1f2a22; font-size: 0.9rem; font-family: inherit; }
.pl2131-field select option { background-color: #ffffff; color: #1f2a22; }
.pl2131-field select:focus-visible, .pl2131-btn:focus-visible { outline: 3px solid #4f7a2f; outline-offset: 2px; }
.pl2131-letter { background-color: #f7f3e6; border: 1px solid #e0d3ad; border-left: 5px solid #b0771f; border-radius: 0 12px 12px 0; padding: 12px 16px; margin-bottom: 14px; }
.pl2131-letter-label { color: #7a5312; }
.pl2131-letter-text { color: #2b2418; background-color: #f7f3e6; max-width: 80ch; }
.pl2131-cash { background-color: #f3f5ef; border: 1px solid #cdd8c8; border-radius: 12px; padding: 12px 16px; margin-top: 14px; }
.pl2131-cash-text { color: #1f2a22; background-color: #f3f5ef; }
.pl2131-cash-text strong { color: #2b4a3a; background-color: #f3f5ef; }
.pl2131-cash-text .pl2131-reveal { display: block; margin-top: 10px; padding-top: 10px; border-top: 1px dashed #93a394; color: #9a3b2e; background-color: #f3f5ef; font-weight: 600; }
.pl2131-feedback { background-color: #ffffff; border: 1px solid #cdd8c8; border-left: 5px solid #2b4a3a; border-radius: 0 16px 16px 0; padding: 14px 18px; margin-bottom: 16px; }
.pl2131-feedback-text { color: #1f2a22; background-color: #ffffff; max-width: 80ch; }
.pl2131-feedback-text.pl2131-warn { color: #9a3b2e; }
.pl2131-actions { display: flex; gap: 10px; margin-bottom: 20px; }
.pl2131-btn { font-family: inherit; font-size: 0.95rem; font-weight: 600; padding: 10px 22px; border-radius: 999px; cursor: pointer; transition: background-color 0.2s ease, color 0.2s ease; }
.pl2131-btn-primary { background-color: #2b4a3a; color: #eef4e8; border: 1px solid #2b4a3a; }
.pl2131-btn-primary:hover { background-color: #4f7a2f; border-color: #4f7a2f; color: #ffffff; }
.pl2131-btn-primary:disabled { background-color: #5b6b60; border-color: #5b6b60; color: #ffffff; cursor: not-allowed; }
.pl2131-btn-secondary { background-color: #ffffff; color: #2b4a3a; border: 1px solid #2b4a3a; }
.pl2131-btn-secondary:hover { background-color: #f3f5ef; }
.pl2131-chart { background-color: #ffffff; border: 1px solid #cdd8c8; border-radius: 16px; padding: 14px 18px; margin-bottom: 16px; }
.pl2131-chart canvas { max-height: 280px; width: 100%; }
.pl2131-chart-title, .pl2131-history-title { font-size: 0.9rem; font-weight: 700; color: #2b4a3a; background-color: #ffffff; margin-bottom: 8px; }
.pl2131-chart-note { font-size: 0.78rem; color: #5b6b60; background-color: #ffffff; margin-top: 6px; }
.pl2131-history { background-color: #ffffff; border: 1px solid #cdd8c8; border-radius: 16px; padding: 14px 18px; overflow-x: auto; }
.pl2131-table { width: 100%; border-collapse: collapse; font-size: 0.85rem; }
.pl2131-table th, .pl2131-table td { padding: 6px 8px; border-bottom: 1px solid #e2e8dd; text-align: left; color: #1f2a22; background-color: #ffffff; }
.pl2131-table th { color: #5b6b60; font-weight: 600; font-size: 0.75rem; letter-spacing: 0.06em; text-transform: uppercase; }
.pl2131-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1f2a22; background-color: #ffffff; padding: 6px 2px; }
.pl2131-cm-score { font-size: 2.6rem; font-weight: 700; color: #2b4a3a; background-color: #ffffff; line-height: 1; }
.pl2131-cm-max { font-size: 1rem; color: #5b6b60; background-color: #ffffff; margin-left: 4px; }
.pl2131-cm-verdict { font-size: 1.15rem; font-weight: 700; color: #4f7a2f; background-color: #ffffff; margin: 6px 0 12px; }
.pl2131-cm-kpis { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; margin-bottom: 12px; }
.pl2131-cm-kpi { background-color: #f3f5ef; border: 1px solid #cdd8c8; border-radius: 10px; padding: 8px 10px; font-size: 0.8rem; color: #3f4f45; }
.pl2131-cm-kpi strong { display: block; font-size: 1.05rem; color: #2b4a3a; background-color: #f3f5ef; }
.pl2131-cm-debrief { font-size: 0.9rem; color: #1f2a22; background-color: #ffffff; margin-bottom: 8px; }
.pl2131-cm-insights { margin: 0; padding-left: 18px; font-size: 0.88rem; color: #1f2a22; background-color: #ffffff; }
.pl2131-cm-insights li { margin-bottom: 4px; }
@media (prefers-reduced-motion: reduce) { .pl2131-container * { transition: none !important; } }
@media (max-width: 768px) {
    .pl2131-container { padding: 12px; }
    .pl2131-kpis { grid-template-columns: repeat(2, 1fr); }
    .pl2131-grid, .pl2131-grid-3, .pl2131-grid-5 { grid-template-columns: 1fr; }
    .pl2131-prog { grid-template-columns: 1fr; }
    .pl2131-prog-head { display: none; }
    .pl2131-cm-kpis { grid-template-columns: 1fr; }
    .pl2131-header h1 { font-size: 1.3rem; }
}

