        SEGMENT_CONV: { gap: 1.0, uni: 1.05, pivot: 1.25 },
        SQUEEZED_FLOOR: -250000,
        VETO_CAP: 60,
        INSOLVENT_CAP: 65
    };

    var PROGS = ['casaluz', 'constr', 'ixchel', 'costa', 'aula'];
    var DISPOSITIONS = ['keep', 'redesign', 'handover', 'close'];
    var CALENDARS = ['verder', 'shared', 'host'];
    var WORKS = ['verder', 'shared', 'host'];
    var COORDS = ['verder', 'coop'];
    var UNRESTRICTED = ['214', '400', '600', '740'];
    var MODELS = ['residual', 'definedfee'];
    var EXTRAS = ['advisory', 'nothing', 'cobrand', 'report'];
    var CONSTRS = ['unchanged', 'skilled', 'fund', 'close'];
    var AULAS = ['unchanged', 'assistants', 'certified', 'close'];
    var DURATIONS = ['17', '28', '42', 'twotier'];
    var HOSTS = ['no', 'ixchel', 'all'];
    var TRANSPARENCIES = ['keep', 'publish', 'commit'];
    var STATEMENTS = ['keep', 'soft', 'full'];
    var PAGES = ['helpbuild', 'fundobserve', 'closed'];
    var CHILDREN = ['yes', 'depends', 'no'];
    var PRICINGS = ['cut', 'hold', 'raise'];
    var SEGMENTS = ['gap', 'uni', 'pivot'];

    class PlacementAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'The Placement';
            this.version = '1.1.0';
            this.ROUNDS = [
                { panel: 'roundPanel1', nameKey: 'r1_name', briefKey: 'r1_brief' },
                { panel: 'roundPanel2', nameKey: 'r2_name', briefKey: 'r2_brief' },
                { panel: 'roundPanel3', nameKey: 'r3_name', briefKey: 'r3_brief' },
                { panel: 'roundPanel4', nameKey: 'r4_name', briefKey: 'r4_brief' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    rounds: [],
                    audit: null,
                    deal: null,
                    portfolio: null,
                    outcome: null,
                    partnerLost: false,
                    insolvent: false,
                    scoreHistory: [],
                    comp: { audit: 0, negotiate: 0, redesign: 0, sell: 0 },
                    performance: { overallScore: 0 },
                    performanceTier: 'beginner'
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._syncControlsFromDecisions(state);
            this._updateBriefing(state);
        }

        _syncControlsFromDecisions(state) {
            var d = (state && state.decisions) || {};
            var set = function(id, val) {
                var el = document.getElementById(id);
                if (el && val !== undefined && val !== null) { el.value = String(val); }
            };
            if (d.round1) { PROGS.forEach(function(p) { set('r1_' + p, d.round1[p]); }); }
            if (d.round2) {
                set('r2_calendar', d.round2.calendar);
                set('r2_work', d.round2.work);
                set('r2_coords', d.round2.coords);
                set('r2_unrestricted', d.round2.unrestricted);
                set('r2_model', d.round2.model);
                set('r2_extra', d.round2.extra);
            }
            if (d.round3) {
                set('r3_constr', d.round3.constr);
                set('r3_aula', d.round3.aula);
                set('r3_duration', d.round3.duration);
                set('r3_host', d.round3.host);
                set('r3_transparency', d.round3.transparency);
            }
            if (d.round4) {
                set('r4_statement', d.round4.statement);
                set('r4_page', d.round4.page);
                set('r4_children', d.round4.children);
                set('r4_pricing', d.round4.pricing);
                set('r4_segment', d.round4.segment);
            }
        }

        _t(key, vars) {
            return window.mySimulation ? window.mySimulation.t(key, vars) : key;
        }

        _cl(key, fallback) {
            var s = this._t(key);
            return s === key ? fallback : s;
        }

        _fmtInt(v) {
            var n = Math.round(Number(v) || 0);
            var s = String(Math.abs(n));
            var out = '';
            while (s.length > 3) { out = ',' + s.slice(-3) + out; s = s.slice(0, -3); }
            return (n < 0 ? '-' : '') + s + out;
        }

        _fmtEurK(v) {
            var k = Math.round((Number(v) || 0) / 1000);
            return (k < 0 ? '−€' : '€') + this._fmtInt(Math.abs(k)) + 'K';
        }

        _fmtEur(v) {
            var n = Math.round(Number(v) || 0);
            return (n < 0 ? '−€' : '€') + this._fmtInt(Math.abs(n));
        }

        // Repaint everything the adapter writes when the language changes, a round is undone or a state is loaded
        _bindRepaint() {
            var self = this;
            var repaint = function() {
                var sim = window.mySimulation;
                if (!sim || !sim.state) { return; }
                self._updateBriefing(sim.state);
                if (typeof sim.updateUI === 'function') { try { sim.updateUI(); } catch (e) { /* silent */ } }
            };
            if (!this._docRepaintBound && typeof document !== 'undefined') {
                document.addEventListener('express:langchanged', repaint);
                this._docRepaintBound = true;
            }
            var sim = window.mySimulation;
            if (!this._busRepaintBound && sim && sim.eventBus && typeof sim.eventBus.on === 'function') {
                sim.eventBus.on('language:changed', repaint);
                sim.eventBus.on('period:undone', repaint);
                sim.eventBus.on('state:loaded', repaint);
                this._busRepaintBound = true;
            }
        }

        _updateBriefing(state) {
            this._bindRepaint();
            var done = (state && state.history) ? state.history.length : 0;
            // The round on screen is the one after the last round in history, so a slow save cannot show a stale round
            var cur = Math.max((state && state.currentPeriod) || 1, done + 1);
            var maxP = (state && state.maxPeriods) || this.ROUNDS.length;
            var finished = done >= maxP || cur > this.ROUNDS.length;
            var i, panel;
            for (i = 0; i < this.ROUNDS.length; i++) {
                panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!finished && (i + 1) === cur) ? 'block' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = finished ? 'none' : 'flex'; }
            var idx = Math.min(cur, this.ROUNDS.length) - 1;
            var nameEl = document.getElementById('roundName');
            if (nameEl) { nameEl.textContent = finished ? this._t('round_done') : this._t(this.ROUNDS[idx].nameKey); }
            var briefEl = document.getElementById('briefingText');
            if (briefEl) { briefEl.innerHTML = finished ? this._t('brief_done') : this._t(this.ROUNDS[idx].briefKey); }
            this._renderDynamic(state);
        }

        _renderDynamic(state) {
            var ds = (state && state.domainState) || {};
            var cashEl = document.getElementById('cashText');
            if (cashEl) { cashEl.innerHTML = ds.portfolio ? this._cashHtml(ds) : (ds.audit ? this._auditCashHtml(ds) : this._t('cash_pending')); }
            var outEl = document.getElementById('outcomeText');
            if (outEl) { outEl.innerHTML = ds.outcome ? this._outcomeHtml(ds) : this._t('outcome_pending'); }
            var fbEl = document.getElementById('feedbackText');
            if (fbEl) {
                var rounds = ds.rounds || [];
                var last = rounds.length ? rounds[rounds.length - 1] : null;
                fbEl.classList.remove('pl2131-warn');
                if (!last) { fbEl.innerHTML = this._t('feedback_empty'); }
                else {
                    fbEl.innerHTML = this._feedbackHtml(ds, last);
                    if (last.verdictKey === 'kept' || last.verdictKey === 'veto' || last.verdictKey === 'purity' || last.verdictKey === 'claim') { fbEl.classList.add('pl2131-warn'); }
                }
            }
        }

        _auditCashHtml(ds) {
            var a = ds.audit || {};
            var v = { gross: this._fmtEurK(a.gross), net: this._fmtEurK(a.net), vol: this._fmtInt(a.volume) };
            return this._t('cash_audit', v) + (a.universityLeft ? '<span class="pl2131-reveal">' + this._t('cash_university_left') + '</span>' : '');
        }

        _cashHtml(ds) {
            var p = ds.portfolio || {};
            var v = { gross: this._fmtEurK(p.gross), overhead: this._fmtEurK(p.overhead), net: this._fmtEurK(p.net), vol: this._fmtInt(p.volume), staff: this._fmtInt(p.staff) };
            var html = this._t('cash_body', v);
            html += '<span class="pl2131-reveal">' + this._t('cash_' + (p.cashKey || 'viable'), v) + '</span>';
            if (ds.partnerLost) { html += '<span class="pl2131-reveal">' + this._t('cash_partner_lost') + '</span>'; }
            return html;
        }

        _outcomeHtml(ds) {
            var o = ds.outcome || {};
            var v = { vol: this._fmtInt(o.volume), net: this._fmtEurK(o.net), staff: this._fmtInt(o.staff), conv: String(Math.round((o.conversion || 0) * 100)) + '%' };
            var html = this._t('outcome_body', v);
            html += '<span class="pl2131-reveal">' + this._t(o.accredited ? 'outcome_accredited' : 'outcome_withdrawn') + '</span>';
            if (o.exposure) { html += '<span class="pl2131-reveal">' + this._t('outcome_exposure') + '</span>'; }
            return html;
        }

        _feedbackHtml(ds, r) {
            var a = ds.audit || {};
            var p = ds.portfolio || {};
            var v = { pts: String(r.pts), max: String(r.max), net: this._fmtEurK(p.net !== undefined ? p.net : a.net), vol: this._fmtInt(p.volume !== undefined ? p.volume : a.volume) };
            return '<strong>' + this._t('fb_points', v) + '</strong> ' + this._t('fb_r' + r.period + '_' + r.verdictKey, v);
        }

        _readSelect(id, allowed) {
            var el = document.getElementById(id);
            if (!el) { return null; }
            var val = String(el.value);
            if (allowed.indexOf(val) === -1) { return null; }
            return val;
        }

        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var state = sim && sim.state ? sim.state : { currentPeriod: 1, history: [] };
            var period = state.currentPeriod || 1;
            var done = state.history ? state.history.length : 0;
            var self = this;
            var warn = function(key) {
                sim.uiManager.showNotification(sim.t(key), 'warning');
                return false;
            };
            if (done >= this.ROUNDS.length || period > this.ROUNDS.length) { return warn('warn_finished'); }
            if (period === 1) {
                var r1 = {};
                var ok = true;
                PROGS.forEach(function(p) { var v = self._readSelect('r1_' + p, DISPOSITIONS); if (!v) { ok = false; } r1[p] = v; });
                if (!ok) { return warn('warn_r1'); }
                decisions.round1 = r1;
                return true;
            }
            if (period === 2) {
                var calendar = this._readSelect('r2_calendar', CALENDARS);
                var work = this._readSelect('r2_work', WORKS);
                var coords = this._readSelect('r2_coords', COORDS);
                var unrestricted = this._readSelect('r2_unrestricted', UNRESTRICTED);
                var model = this._readSelect('r2_model', MODELS);
                var extra = this._readSelect('r2_extra', EXTRAS);
                if (!calendar || !work || !coords || !unrestricted || !model || !extra) { return warn('warn_r2'); }
                decisions.round2 = { calendar: calendar, work: work, coords: coords, unrestricted: parseInt(unrestricted, 10), model: model, extra: extra };
                return true;
            }
            if (period === 3) {
                var constr = this._readSelect('r3_constr', CONSTRS);
                var aula = this._readSelect('r3_aula', AULAS);
                var duration = this._readSelect('r3_duration', DURATIONS);
                var host = this._readSelect('r3_host', HOSTS);
                var transparency = this._readSelect('r3_transparency', TRANSPARENCIES);
                if (!constr || !aula || !duration || !host || !transparency) { return warn('warn_r3'); }
                decisions.round3 = { constr: constr, aula: aula, duration: duration, host: host, transparency: transparency };
                return true;
            }
            if (period === 4) {
                var statement = this._readSelect('r4_statement', STATEMENTS);
                var page = this._readSelect('r4_page', PAGES);
                var children = this._readSelect('r4_children', CHILDREN);
                var pricing = this._readSelect('r4_pricing', PRICINGS);
                var segment = this._readSelect('r4_segment', SEGMENTS);
                if (!statement || !page || !children || !pricing || !segment) { return warn('warn_r4'); }
                decisions.round4 = { statement: statement, page: page, children: children, pricing: pricing, segment: segment };
                return true;
            }
            return warn('warn_finished');
        }

        calculateResults(state) {
            var out = this._computeRound(state);
            var self = this;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state); }, 400);
            return out;
        }

        // Round model. Recomputed from decisions so a resubmit of the same period is idempotent.
        _computeRound(state) {
            var ds = state.domainState;
            var d = state.decisions || {};
            var period = state.currentPeriod || 1;
            var rec = { period: period, pts: 0, max: 0, verdictKey: 'ok' };
            ds.rounds = (ds.rounds || []).slice(0, period - 1);
            if (period === 1) { rec = this._round1(ds, d); }
            if (period === 2) { rec = this._round2(ds, d); }
            if (period === 3) { rec = this._round3(ds, d); }
            if (period === 4) { rec = this._round4(ds, d); }
            rec.period = period;
            ds.rounds[period - 1] = rec;
            ds.rounds.length = period;
            this._resum(ds);
            var score = this._composite(ds);
            ds.performance = { overallScore: score };
            ds.performanceTier = this._tier(score);
            ds.scoreHistory = (ds.scoreHistory || []).slice(0, period - 1);
            ds.scoreHistory[period - 1] = score;
            ds.scoreHistory.length = period;
            var snap = ds.outcome || ds.portfolio || ds.audit || {};
            return {
                period: period,
                roundPoints: rec.pts,
                roundMax: rec.max,
                net: (snap.net !== undefined) ? snap.net : C.NET_2025,
                volume: (snap.volume !== undefined) ? snap.volume : 2140,
                partner: ds.partnerLost ? 'lost' : 'active',
                score: score,
                overallScore: score
            };
        }

        _resum(ds) {
            var r = ds.rounds || [];
            ds.comp = { audit: r[0] ? r[0].pts : 0, negotiate: r[1] ? r[1].pts : 0, redesign: r[2] ? r[2].pts : 0, sell: r[3] ? r[3].pts : 0 };
        }

        _composite(ds) {
            var c = (ds && ds.comp) || {};
            var total = (c.audit || 0) + (c.negotiate || 0) + (c.redesign || 0) + (c.sell || 0);
            if (ds && ds.partnerLost) { total = Math.min(C.VETO_CAP, total); }
            if (ds && ds.insolvent) { total = Math.min(C.INSOLVENT_CAP, total); }
            return Math.max(0, Math.min(100, Math.round(total)));
        }

        _tier(score) {
            if (score >= 75) { return 'excellent'; }
            if (score >= 55) { return 'good'; }
            return 'beginner';
        }

        _dispositionFactor(disp) {
            if (disp === 'close') { return { vol: 0, gross: 0 }; }
            if (disp === 'handover') { return { vol: 1, gross: 0.4 }; }
            return { vol: 1, gross: 1 };
        }

        _round1(ds, d) {
            var r1 = d.round1 || {};
            var pts = 0, gross = 0, volume = 0;
            var self = this;
            PROGS.forEach(function(p) {
                var disp = r1[p] || 'keep';
                pts += (C.DISPOSITION_PTS[p] || {})[disp] || 0;
                var f = self._dispositionFactor(disp);
                gross += C.PROGRAMMES[p].gross * f.gross;
                volume += C.PROGRAMMES[p].vol * f.vol;
            });
            var casaClosed = r1.casaluz === 'close';
            var universityLeft = !casaClosed;
            if (universityLeft) { gross *= (1 - C.UNIVERSITY_SHARE); volume *= (1 - C.UNIVERSITY_SHARE); }
            var overhead = C.FIXED_OVERHEAD + C.VAR_OVERHEAD * volume;
            var net = gross - overhead;
            var verdictKey = 'evidence';
            if (!casaClosed) { verdictKey = 'kept'; }
            else if (r1.constr === 'keep' && r1.aula === 'keep') { verdictKey = 'blind'; }
            ds.audit = { dispositions: Object.assign({}, r1), casaClosed: casaClosed, universityLeft: universityLeft, gross: Math.round(gross), volume: Math.round(volume), net: Math.round(net) };
            ds.deal = null;
            ds.portfolio = null;
            ds.outcome = null;
            ds.partnerLost = false;
            ds.insolvent = false;
            return { pts: pts, max: 22, verdictKey: verdictKey, casaClosed: casaClosed, net: Math.round(net) };
        }

        _dealFrom(r2) {
            var u = Number(r2.unrestricted) || C.UNRESTRICTED_NOW;
            var accepted = (r2.work === 'host') && (r2.calendar !== 'verder') && (u >= 600) && (r2.coords === 'coop' || u >= 740);
            var perVol;
            if (r2.model === 'definedfee') { perVol = C.DEFINED_FEE - C.DEFINED_FEE_COST; }
            else { perVol = C.IXCHEL_MARGIN_NOW - (u - C.UNRESTRICTED_NOW) + (r2.coords === 'coop' ? C.COORD_SAVING : 0); }
            return { calendar: r2.calendar, work: r2.work, coords: r2.coords, unrestricted: u, model: r2.model, extra: r2.extra, accepted: accepted, ixchelPerVol: perVol, ixchelGross: accepted ? Math.round(C.PROGRAMMES.ixchel.vol * perVol) : 0 };
        }

        _round2(ds, d) {
            var r2 = d.round2 || {};
            var deal = this._dealFrom(r2);
            ds.deal = deal;
            ds.partnerLost = !deal.accepted;
            ds.portfolio = null;
            ds.outcome = null;
            ds.insolvent = false;
            var pts = 0;
            pts += C.WORK_PTS[r2.work] || 0;
            pts += C.CAL_PTS[r2.calendar] || 0;
            pts += C.COORD_PTS[r2.coords] || 0;
            pts += C.UNRESTRICTED_PTS[deal.unrestricted] || 0;
            pts += C.MODEL_PTS[r2.model] || 0;
            var verdictKey = 'terms';
            if (!deal.accepted) { verdictKey = 'veto'; }
            else if (r2.extra === 'advisory') { verdictKey = 'voice'; }
            else if (r2.model === 'definedfee') { verdictKey = 'business'; }
            return { pts: pts, max: 26, verdictKey: verdictKey, accepted: deal.accepted, unrestricted: deal.unrestricted, ixchelGross: deal.ixchelGross };
        }

        _portfolioFrom(ds, d) {
            var r1 = (ds.audit && ds.audit.dispositions) || d.round1 || {};
            var deal = ds.deal || this._dealFrom(d.round2 || {});
            var r3 = d.round3 || {};
            var lines = {};
            var dur = C.DURATION_MODEL[r3.duration] || C.DURATION_MODEL['17'];
            var hostM = C.HOST_MODEL[r3.host] || C.HOST_MODEL.no;
            var self = this;
            var lineFor = function(p, model) {
                var disp = r1[p] || 'keep';
                var base = C.PROGRAMMES[p];
                if (disp === 'close') { return { vol: 0, gross: 0 }; }
                if (disp === 'handover') { return { vol: base.vol, gross: base.gross * 0.4 }; }
                var m = model || { vol: 1, gross: 1 };
                return { vol: base.vol * m.vol * dur.vol, gross: base.gross * m.gross * dur.gross * hostM.gross };
            };
            lines.casaluz = (r1.casaluz === 'close') ? { vol: 0, gross: 0 } : lineFor('casaluz', null);
            lines.constr = lineFor('constr', C.CONSTR_MODEL[r3.constr] || C.CONSTR_MODEL.unchanged);
            lines.aula = lineFor('aula', C.AULA_MODEL[r3.aula] || C.AULA_MODEL.unchanged);
            lines.costa = lineFor('costa', null);
            if (r1.ixchel === 'close' || !deal.accepted) { lines.ixchel = { vol: 0, gross: 0 }; }
            else if (r1.ixchel === 'handover') { lines.ixchel = { vol: C.PROGRAMMES.ixchel.vol, gross: C.PROGRAMMES.ixchel.gross * 0.4 }; }
            else { lines.ixchel = { vol: C.PROGRAMMES.ixchel.vol, gross: deal.ixchelGross }; }
            var gross = 0, volume = 0;
            PROGS.forEach(function(p) { gross += lines[p].gross; volume += lines[p].vol; });
            var universityLeft = r1.casaluz !== 'close';
            if (universityLeft) { gross *= (1 - C.UNIVERSITY_SHARE); volume *= (1 - C.UNIVERSITY_SHARE); }
            var overhead = C.FIXED_OVERHEAD * hostM.fixed + C.VAR_OVERHEAD * hostM.variable * volume;
            var net = gross - overhead;
            var cashKey = net >= 0 ? 'viable' : (net >= C.SQUEEZED_FLOOR ? 'squeezed' : 'insolvent');
            var staff = Math.round(C.STAFF_UTRECHT * (r3.host === 'all' ? 0.6 : 1) + (C.STAFF_TOTAL - C.STAFF_UTRECHT) * (volume / 2140));
            return { lines: lines, gross: Math.round(gross), volume: Math.round(volume), overhead: Math.round(overhead), net: Math.round(net), cashKey: cashKey, staff: staff, duration: r3.duration, host: r3.host, transparency: r3.transparency, constr: r3.constr, aula: r3.aula, universityLeft: universityLeft };
        }

        _round3(ds, d) {
            var r3 = d.round3 || {};
            var p = this._portfolioFrom(ds, d);
            ds.portfolio = p;
            ds.outcome = null;
            ds.insolvent = p.cashKey === 'insolvent';
            var pts = 0;
            pts += C.CONSTR_PTS[r3.constr] || 0;
            pts += C.AULA_PTS[r3.aula] || 0;
            pts += C.DURATION_PTS[r3.duration] || 0;
            pts += C.HOST_PTS[r3.host] || 0;
            pts += C.TRANSPARENCY_PTS[r3.transparency] || 0;
            var verdictKey = 'reform';
            if (p.cashKey === 'insolvent') { verdictKey = 'purity'; }
            else if (r3.constr === 'unchanged' && r3.aula === 'unchanged') { verdictKey = 'cosmetic'; }
            return { pts: pts, max: 26, verdictKey: verdictKey, net: p.net, cashKey: p.cashKey };
        }

        _round4(ds, d) {
            var r4 = d.round4 || {};
            var p = ds.portfolio || this._portfolioFrom(ds, d);
            ds.portfolio = p;
            var r1d = (ds.audit && ds.audit.dispositions) || d.round1 || {};
            // A programme closed in Round 1 no longer runs, so its Round 3 select cannot fail the university tests
            var constrGone = r1d.constr === 'close' || p.constr === 'close';
            var aulaGone = r1d.aula === 'close' || p.aula === 'close';
            var accredited = !p.universityLeft && r4.children !== 'yes' && (constrGone || p.constr !== 'unchanged') && (aulaGone || p.aula !== 'unchanged');
            // Recruiting from accredited university programmes only lifts conversion only while the university accredits
            var segConv = (r4.segment === 'uni' && !accredited) ? 1 : (C.SEGMENT_CONV[r4.segment] || 1);
            var conv = (C.STATEMENT_CONV[r4.statement] || 1) * (C.CHILDREN_CONV[r4.children] || 1) * segConv * (p.transparency === 'commit' ? 1.05 : 1);
            var pr = C.PRICING_MODEL[r4.pricing] || C.PRICING_MODEL.hold;
            var volFactor = conv * pr.vol * (accredited ? 1 : (1 - C.UNIVERSITY_SHARE));
            var volume = 0, gross = 0;
            var hostM = C.HOST_MODEL[p.host] || C.HOST_MODEL.no;
            PROGS.forEach(function(pn) {
                var line = p.lines[pn];
                if (pn === 'ixchel') { volume += line.vol; gross += line.gross; return; }
                volume += line.vol * volFactor;
                gross += line.gross * volFactor * pr.gross;
            });
            var overhead = C.FIXED_OVERHEAD * hostM.fixed + C.VAR_OVERHEAD * hostM.variable * volume;
            var net = gross - overhead;
            var exposure = r4.statement === 'keep' && p.transparency === 'keep';
            var staff = Math.round(C.STAFF_UTRECHT * (p.host === 'all' ? 0.6 : 1) + (C.STAFF_TOTAL - C.STAFF_UTRECHT) * (volume / 2140));
            ds.outcome = { conversion: conv * pr.vol, volume: Math.round(volume), gross: Math.round(gross), net: Math.round(net), accredited: accredited, exposure: exposure, staff: staff };
            // Recomputed on every submit so an undone insolvent Round 4 does not keep the cap
            ds.insolvent = (p.cashKey === 'insolvent') || (net < C.SQUEEZED_FLOOR);
            var pts = 0;
            pts += C.STATEMENT_PTS[r4.statement] || 0;
            pts += (constrGone ? C.PAGE_PTS_CLOSED : C.PAGE_PTS)[r4.page] || 0;
            pts += C.CHILDREN_PTS[r4.children] || 0;
            pts += C.PRICING_PTS[r4.pricing] || 0;
            pts += C.SEGMENT_PTS[r4.segment] || 0;
            var verdictKey = 'mixed';
            if (r4.statement === 'keep') { verdictKey = 'claim'; }
            else if (r4.statement === 'full' && r4.children === 'no') { verdictKey = 'honest'; }
            return { pts: pts, max: 26, verdictKey: verdictKey, accredited: accredited, net: Math.round(net), volume: Math.round(volume) };
        }

