        getHint(state, results) {
            var ds = state.domainState || {};
            var r = (ds.rounds || [])[(results.period || 1) - 1] || {};
            if (results.period === 1) {
                if (r.verdictKey === 'kept') { return this._t('hint_kept'); }
                if (r.verdictKey === 'blind') { return this._t('hint_blind'); }
                return this._t('hint_r1_ok');
            }
            if (results.period === 2) {
                if (r.verdictKey === 'veto') { return this._t('hint_veto'); }
                if (r.verdictKey === 'voice') { return this._t('hint_voice'); }
                if (r.verdictKey === 'terms') { return this._t('hint_residual'); }
                return this._t('hint_r2_ok');
            }
            if (results.period === 3) {
                if (r.verdictKey === 'purity') { return this._t('hint_purity'); }
                if (r.verdictKey === 'cosmetic') { return this._t('hint_cosmetic'); }
                if (r.cashKey === 'squeezed') { return this._t('hint_squeezed'); }
                return this._t('hint_r3_ok');
            }
            if (results.period === 4) {
                if (r.verdictKey === 'claim') { return this._t('hint_claim'); }
                if (!r.accredited) { return this._t('hint_accreditation'); }
                return this._t('hint_r4_ok');
            }
            return null;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var ds = window.mySimulation.state.domainState;
            var o = ds.outcome || {};
            var p = ds.portfolio || {};
            var hist = ds.scoreHistory || [];
            var composite = this._composite(ds);
            var performance = 'Beginner';
            if (composite >= 55) { performance = 'Good'; }
            if (composite >= 75) { performance = 'Excellent'; }
            var r1 = (ds.rounds || [])[0] || {};
            var r3 = (ds.rounds || [])[2] || {};
            var r4 = (ds.rounds || [])[3] || {};
            var insights = [];
            insights.push(r1.casaClosed ? this._t('insight_casaluz_closed') : this._t('insight_casaluz_kept'));
            insights.push(ds.partnerLost ? this._t('insight_partner_lost') : this._t('insight_partner_kept'));
            insights.push(r3.verdictKey === 'purity' ? this._t('insight_purity') : (r3.verdictKey === 'cosmetic' ? this._t('insight_cosmetic') : this._t('insight_reform')));
            insights.push(r4.verdictKey === 'claim' ? this._t('insight_claim') : this._t('insight_honest'));
            insights.push(this._t('insight_next'));
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                net: (o.net !== undefined) ? o.net : (p.net !== undefined ? p.net : null),
                volume: (o.volume !== undefined) ? o.volume : (p.volume !== undefined ? p.volume : null),
                staff: (o.staff !== undefined) ? o.staff : null,
                partnerLost: !!ds.partnerLost,
                accredited: !!o.accredited,
                rounds: hist.length,
                performance: performance,
                performanceKey: performance.toLowerCase(),
                performanceLabel: this._cl('grade_' + performance.toLowerCase(), performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="pl2131-cm">'
                + '<div class="pl2131-cm-score">' + score + '<span class="pl2131-cm-max">/100</span></div>'
                + '<div class="pl2131-cm-verdict">' + (s.performanceLabel || s.performance || '') + '</div>'
                + '<div class="pl2131-cm-kpis">'
                + '<div class="pl2131-cm-kpi">' + this._t('cm_kpi_net') + '<strong>' + (s.net === null || s.net === undefined ? '—' : this._fmtEurK(s.net)) + '</strong></div>'
                + '<div class="pl2131-cm-kpi">' + this._t('cm_kpi_volume') + '<strong>' + (s.volume === null || s.volume === undefined ? '—' : this._fmtInt(s.volume)) + '</strong></div>'
                + '<div class="pl2131-cm-kpi">' + this._t('cm_kpi_partner') + '<strong>' + this._t(s.partnerLost ? 'partner_lost' : 'partner_active') + '</strong></div>'
                + '<div class="pl2131-cm-kpi">' + this._t('cm_kpi_uni') + '<strong>' + this._t(s.accredited ? 'uni_accredited' : 'uni_withdrawn') + '</strong></div>'
                + '</div>'
                + '<div class="pl2131-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="pl2131-cm-insights">' + items + '</ul>'
                + '</div>';
        }

